"""Tests for roman.py."""

import pytest

from roman import to_roman, from_roman


# ── to_roman: basic conversions ──────────────────────────────────────────────

class TestToRomanBasic:
    def test_one(self):
        assert to_roman(1) == "I"

    def test_two(self):
        assert to_roman(2) == "II"

    def test_three(self):
        assert to_roman(3) == "III"

    def test_four(self):
        assert to_roman(4) == "IV"

    def test_five(self):
        assert to_roman(5) == "V"

    def test_nine(self):
        assert to_roman(9) == "IX"

    def test_ten(self):
        assert to_roman(10) == "X"

    def test_forty(self):
        assert to_roman(40) == "XL"

    def test_fifty(self):
        assert to_roman(50) == "L"

    def test_ninety(self):
        assert to_roman(90) == "XC"

    def test_hundred(self):
        assert to_roman(100) == "C"

    def test_four_hundred(self):
        assert to_roman(400) == "CD"

    def test_five_hundred(self):
        assert to_roman(500) == "D"

    def test_nine_hundred(self):
        assert to_roman(900) == "CM"

    def test_thousand(self):
        assert to_roman(1000) == "M"

    def test_max(self):
        assert to_roman(3999) == "MMMCMXCIX"

    def test_sample_numbers(self):
        assert to_roman(1994) == "MCMXCIV"
        assert to_roman(2023) == "MMXXIII"
        assert to_roman(1666) == "MDCLXVI"


# ── to_roman: boundary and range errors ──────────────────────────────────────

class TestToRomanRange:
    def test_zero_raises(self):
        with pytest.raises(ValueError):
            to_roman(0)

    def test_negative_raises(self):
        with pytest.raises(ValueError):
            to_roman(-1)

    def test_above_max_raises(self):
        with pytest.raises(ValueError):
            to_roman(4000)

    def test_very_large_raises(self):
        with pytest.raises(ValueError):
            to_roman(10000)


# ── to_roman: type errors ───────────────────────────────────────────────────

class TestToRomanTypes:
    def test_float_raises(self):
        with pytest.raises(ValueError):
            to_roman(1.5)

    def test_string_raises(self):
        with pytest.raises(ValueError):
            to_roman("1")

    def test_none_raises(self):
        with pytest.raises(ValueError):
            to_roman(None)

    def test_bool_raises(self):
        with pytest.raises(ValueError):
            to_roman(True)

    def test_list_raises(self):
        with pytest.raises(ValueError):
            to_roman([1])


# ── from_roman: basic conversions ────────────────────────────────────────────

class TestFromRomanBasic:
    def test_i(self):
        assert from_roman("I") == 1

    def test_ii(self):
        assert from_roman("II") == 2

    def test_iii(self):
        assert from_roman("III") == 3

    def test_iv(self):
        assert from_roman("IV") == 4

    def test_v(self):
        assert from_roman("V") == 5

    def test_ix(self):
        assert from_roman("IX") == 9

    def test_x(self):
        assert from_roman("X") == 10

    def test_xl(self):
        assert from_roman("XL") == 40

    def test_l(self):
        assert from_roman("L") == 50

    def test_xc(self):
        assert from_roman("XC") == 90

    def test_c(self):
        assert from_roman("C") == 100

    def test_cd(self):
        assert from_roman("CD") == 400

    def test_d(self):
        assert from_roman("D") == 500

    def test_cm(self):
        assert from_roman("CM") == 900

    def test_m(self):
        assert from_roman("M") == 1000

    def test_mmm_cm_xc_ix(self):
        assert from_roman("MMMCMXCIX") == 3999

    def test_sample_numbers(self):
        assert from_roman("MCMXCIV") == 1994
        assert from_roman("MMXXIII") == 2023
        assert from_roman("MDCLXVI") == 1666


# ── from_roman: invalid numerals ─────────────────────────────────────────────

class TestFromRomanInvalid:
    """Every case listed in the spec plus extras."""

    def test_empty_string(self):
        with pytest.raises(ValueError):
            from_roman("")

    def test_repeated_iiiii(self):
        with pytest.raises(ValueError):
            from_roman("IIII")

    def test_repeated_vv(self):
        with pytest.raises(ValueError):
            from_roman("VV")

    def test_ic(self):
        with pytest.raises(ValueError):
            from_roman("IC")

    def test_xm(self):
        with pytest.raises(ValueError):
            from_roman("XM")

    def test_mmmm(self):
        with pytest.raises(ValueError):
            from_roman("MMMM")

    def test_banana(self):
        with pytest.raises(ValueError):
            from_roman("banana")

    def test_non_uppercase_raises(self):
        with pytest.raises(ValueError):
            from_roman("iv")

    def test_non_alpha_raises(self):
        with pytest.raises(ValueError):
            from_roman("I1")

    def test_invalid_subtractive_vi(self):
        """V cannot subtract — VI is valid but IVI is not."""
        with pytest.raises(ValueError):
            from_roman("IVI")

    def test_zulu_raises(self):
        with pytest.raises(ValueError):
            from_roman("Z")

    def test_duplicate_subtractive_cmcm(self):
        with pytest.raises(ValueError):
            from_roman("CMCM")

    def test_numeric_string_raises(self):
        with pytest.raises(ValueError):
            from_roman("42")


# ── from_roman: type errors ──────────────────────────────────────────────────

class TestFromRomanTypes:
    def test_int_raises(self):
        with pytest.raises(ValueError):
            from_roman(1)

    def test_none_raises(self):
        with pytest.raises(ValueError):
            from_roman(None)

    def test_float_raises(self):
        with pytest.raises(ValueError):
            from_roman(1.0)

    def test_list_raises(self):
        with pytest.raises(ValueError):
            from_roman(["I"])


# ── round-trip invariant ─────────────────────────────────────────────────────

class TestRoundTrip:
    def test_all_values_1_to_3999(self):
        for n in range(1, 4000):
            assert from_roman(to_roman(n)) == n
